CREATE TABLE IF NOT EXISTS shop_rebate_order(order_id BIGINT PRIMARY KEY,company_id BIGINT NOT NULL,rules_json MEDIUMTEXT NOT NULL,used_amount BIGINT NOT NULL DEFAULT 0,returned_amount BIGINT NOT NULL DEFAULT 0,state VARCHAR(20) NOT NULL DEFAULT 'reserved',INDEX rebate_company(company_id));
CREATE TABLE IF NOT EXISTS shop_rebate_period(company_id BIGINT NOT NULL,period CHAR(7) NOT NULL,amount BIGINT NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'waiting',note VARCHAR(200) NOT NULL DEFAULT '',updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(company_id,period));
CREATE TABLE IF NOT EXISTS shop_rebate_ledger(id BIGINT PRIMARY KEY AUTO_INCREMENT,company_id BIGINT NOT NULL,event_key VARCHAR(100) NOT NULL UNIQUE,delta BIGINT NOT NULL,order_id BIGINT NULL,period CHAR(7) NULL,note VARCHAR(200) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX rebate_balance(company_id));
